def unit_name_for(cls: str) -> str:
    """A DOS 8.3 unit name for a form class.

    Delphi 1's compiler runs on DOS/Win16, so every unit file name fits 8.3;
    the original's names are not in the image, so the class name is upper-cased
    and truncated.  A unit may not declare an identifier equal to its own name
    (`Error 4: Duplicate identifier`), `TSabowin` is exactly eight characters,
    so a colliding name drops the leading `T`.
    """
    name = cls.upper()[:8]
    if name == cls.upper():
        name = cls.upper().lstrip("T")[:8]
    return name


def segment_of_class(cls: str) -> int:
    """The segment whose evidence lists *cls*."""
    for index, (_name, classes, _evidence) in UNITS.items():
        if cls in classes:
            return index
    raise SystemExit(f"no segment evidence for {cls}")


def form_units() -> dict[int, list[tuple[str, str]]]:
    """segment index -> [(unit name, form class)], in link order."""
    out: dict[int, list[tuple[str, str]]] = {}
    for cls in FORM_ORDER:
        out.setdefault(segment_of_class(cls), []).append((unit_name_for(cls), cls))
    return out


