def event_for(handlers: dict[str, str], method: str) -> str | None:
    """The `On...` event a form stream wires *method* to (case-insensitively:
    the stream and the RTTI table spell handler names differently)."""
    for handler, event in handlers.items():
        if handler.lower() == method.lower():
            return event
    return None


def wrap_uses(names: list[str], opening: str = "uses ") -> str:
    """A `uses` clause wrapped to fit Delphi 1's 126-character line limit
    (`Error 11: Line too long`); the continuation lines are plain indent."""
    lines: list[str] = []
    current = opening
    for position, name in enumerate(names):
        token = name + ("," if position < len(names) - 1 else ";")
        if len(current) + len(token) + 1 > 100:
            lines.append(current.rstrip())
            current = "  "
        current += token + " "
    lines.append(current.rstrip())
    return "\n".join(lines)


#: Delphi 1 refuses a source line longer than 126 characters (`Error 11: Line
#: too long`), which is the limit `wrap_uses` already keeps to. Declarations aim
#: six under it so a long method name costs a line break instead of a failed
#: build: `UeberschriftbildMouseDown` reached 127 characters.
DCC_LINE_LIMIT = 126


def wrap_decl(decl: str, indent: str = "", width: int = DCC_LINE_LIMIT - 6) -> str:
    """Split a method declaration at its parameter separators so every line fits.

    A line break inside a parameter list is whitespace to DCC, so the signature
    the compiler reads is the one the unwrapped line would have written; only the
    source bytes move. Continuation lines take two spaces past `indent`, and each
    break falls after a `;`, which is why the pieces rejoin to the original
    declaration with a single space between them.

    A parameter that cannot fit on a line of its own is a limit rather than a
    formatting problem, and is reported with the declaration that produced it.
    """
    if len(indent) + len(decl) <= width:
        return indent + decl
    opening = decl.find("(")
    closing = decl.rfind(")")
    if opening < 0 or closing <= opening:
        raise ValueError(f"cannot wrap {decl!r}: no parameter list to break at")
    breaks: list[int] = []
    search = opening + 1
    while True:
        at = decl.find("; ", search)
        if at < 0 or at >= closing:
            break
        breaks.append(at + 2)          # the next line starts after the space
        search = at + 2
    continuation = indent + "  "
    lines: list[str] = []
    start = 0
    while start < len(decl):
        prefix = indent if not lines else continuation
        chosen: int | None = None
        for nxt in [*breaks, len(decl)]:
            if nxt <= start:
                continue
            end = len(decl) if nxt == len(decl) else nxt - 1
            if len(prefix) + len(decl[start:end]) <= width:
                chosen = end
            else:
                break
        if chosen is None:
            raise ValueError(
                f"cannot wrap {decl!r}: no parameter boundary fits a "
                f"{width}-character line from {decl[start:]!r}")
        lines.append(prefix + decl[start:chosen])
        start = chosen + 1              # the break point leaves one space behind
    return "\n".join(lines)


def _near(note: str) -> bool:
    """True when a free-body note carries the `, near` marker, wherever it sits.

    The marker used to be read with `endswith(", near")`, so an explanation
    appended after it flipped the row to far and emitted a bogus interface line
    (AUKTION.PAS:43). `{$F+}` puts the four-byte far return below the parameters
    and shifts every slot, so a near body is declared and defined under `{$F-}`
    and kept out of the interface. The token must not open a longer word:
    `", nearby"` is not the marker.
    """
    at = note.find(", near")
    while at >= 0:
        after = at + len(", near")
        if after == len(note) or not note[after].isalnum():
            return True
        at = note.find(", near", after)
    return False


